$stmt->execute(['id' => $user_id]);

// Java with JDBC
PreparedStatement stmt = conn.prepareStatement('SELECT * FROM users WHERE id = ?');
stmt.setInt(1, userId);

// PHP - avoid exec()
// Dangerous:
exec($user_input);
// Safe:
$output = shell_exec('ls /safe/directory');  # Fixed command

// JavaScript - avoid eval()
// Dangerous:
eval(userInput);
// Safe:
let result = Function('"use strict";return (' + userInput + ')')();

// PHP command validation
function safeShellExec($baseCommand, $userInput) {
    if (!preg_match('/^[a-zA-Z0-9._-]+$/', $userInput)) {
        throw new Exception('Invalid input');
    }

    $safeInput = escapeshellarg($userInput);
    $fullCommand = $baseCommand . ' ' . $safeInput;

    return shell_exec($fullCommand);
}

